<script setup lang="ts">
import {computed,ref} from 'vue'
import {onLoad} from '@dcloudio/uni-app'
import {packingApi} from '../../api/packing.api'
import type{PackingPackagingStatistic,PackingZoneWeightStatistic,PackingIncomeStatistic,PackingCottonSummary}from'../../models/packing'
import {sessionStore} from '@/store/session'
import WareState from '@/shared/components/WareState.vue'
import SessionDatePicker from '@/shared/components/SessionDatePicker.vue'
type TabKey='packaging'|'zoneWeight'|'income'|'cotton'
const allTabs=[{key:'packaging' as TabKey,label:'打包包装统计',capability:'packing.statistics.packaging'},{key:'zoneWeight' as TabKey,label:'分区重量统计',capability:'packing.statistics.zoneWeight'},{key:'income' as TabKey,label:'打包收益统计',capability:'packing.statistics.income'},{key:'cotton' as TabKey,label:'保温棉',capability:'packing.statistics.cotton'}]
const tabs=computed(()=>allTabs.filter(item=>sessionStore.can(item.capability)))
const active=ref<TabKey>('packaging'),date=ref(''),endDate=ref(''),loading=ref(false),datePicker=ref<'date'|'end'|null>(null)
const packaging=ref<PackingPackagingStatistic[]>([]),weights=ref<PackingZoneWeightStatistic[]>([]),income=ref<PackingIncomeStatistic[]>([]),cotton=ref<PackingCottonSummary>({total:0,rows:[]})
const name=ref(''),incomeType=ref(0),zone=ref(''),zones=ref<string[]>([]),zoneVisible=ref(false),typeVisible=ref(false),incomeTypes=['全部类型','普通货架','城市仓货架']
async function load(){if(!tabs.value.length)return;loading.value=true;try{if(active.value==='packaging')packaging.value=await packingApi.packagingStatistics(date.value);else if(active.value==='zoneWeight')weights.value=await packingApi.zoneWeightStatistics(date.value,endDate.value);else if(active.value==='income')income.value=await packingApi.incomeStatistics(date.value,name.value,incomeType.value);else cotton.value=await packingApi.cottonStatistics(date.value,zone.value)}finally{loading.value=false}}
function changeTab(key:TabKey){active.value=key;load()}
function setDate(value:string){if(datePicker.value==='end')endDate.value=value;else date.value=value;load()}
function selectZone(value:string){zone.value=value;zoneVisible.value=false;load()}
function selectType(value:number){incomeType.value=value;typeVisible.value=false;load()}
onLoad(async q=>{date.value=String(q?.date||new Date().toISOString().slice(0,10));endDate.value=date.value;active.value=tabs.value[0]?.key||'packaging';zones.value=await packingApi.zones(date.value);load()})
</script>
<template><view class="page"><WareState v-if="!tabs.length" type="forbidden" title="暂无业务数据统计权限" description="请联系管理员开通至少一个打包统计能力"/><template v-else>
  <scroll-view scroll-x class="tabs"><view class="tab-row"><text v-for="item in tabs" :key="item.key" :class="{active:active===item.key}" @click="changeTab(item.key)">{{item.label}}</text></view></scroll-view>
  <view v-if="active==='zoneWeight'" class="toolbar range"><view class="filter-trigger date-trigger" @click="datePicker='date'"><text class="calendar-icon">▣</text><text>{{date}}</text><i/></view><text class="range-separator">至</text><view class="filter-trigger date-trigger" @click="datePicker='end'"><text class="calendar-icon">▣</text><text>{{endDate}}</text><i/></view></view>
  <view v-else-if="active==='income'" class="toolbar income-filter"><input v-model="name" placeholder="打包人员" confirm-type="search" @confirm="load"/><view class="filter-trigger date-trigger" @click="datePicker='date'"><text class="calendar-icon">▣</text><text>{{date}}</text><i/></view><view class="filter-trigger" @click="typeVisible=true"><text>{{incomeTypes[incomeType]}}</text><i/></view></view>
  <view v-else-if="active==='cotton'" class="toolbar cotton-filter"><view class="filter-trigger date-trigger" @click="datePicker='date'"><text class="calendar-icon">▣</text><text>{{date}}</text><i/></view><text class="cotton-total">共 {{cotton.total}} 层</text><view class="filter-trigger" @click="zoneVisible=true"><text>{{zone?zone+'区':'全部分区'}}</text><i/></view></view>
  <view v-else class="toolbar"><view class="filter-trigger date-trigger" @click="datePicker='date'"><text class="calendar-icon">▣</text><text>{{date}}</text><i/></view></view>
  <WareState v-if="loading" type="loading" title="正在统计"/><template v-else>
    <view v-if="active==='packaging'&&packaging.length" class="table two"><view class="thead"><text>包装</text><text>数量</text></view><view v-for="row in packaging" :key="row.name" class="tr"><text>{{row.name}}</text><text>{{row.num}}</text></view></view>
    <view v-else-if="active==='zoneWeight'&&weights.length" class="table three"><view class="thead"><text>分区</text><text>货架数量</text><text>合计重量(kg)</text></view><view v-for="row in weights" :key="row.zone" class="tr"><text>{{row.zone==='其他'?'其他':row.zone+'区'}}</text><text>{{row.shelfNum}}</text><text>{{row.totalWeight.toFixed(2)}}</text></view></view>
    <view v-else-if="active==='income'&&income.length" class="table income"><view class="thead"><text>打包员</text><text>货架/城市仓</text><text>重量</text><text>预计收益</text></view><view v-for="row in income" :key="row.id" class="tr"><text>{{row.packageUserName}}\nID:{{row.packageUserId}}</text><text>{{row.wareName||'#'+row.shelfNo}}</text><text>{{row.totalWeight.toFixed(3)}}</text><text class="danger">{{row.price.toFixed(2)}}</text></view></view>
    <view v-else-if="active==='cotton'&&cotton.rows.length" class="table two"><view class="thead"><text>货架号</text><text>保温棉数量</text></view><view v-for="row in cotton.rows" :key="row.shelfNo" class="tr"><text>{{row.shelfNo}}</text><text>{{row.num}}</text></view></view>
    <WareState v-else type="empty" title="暂无统计数据" description="可调整日期或筛选条件后重试"/>
  </template></template>
  <SessionDatePicker :model-value="datePicker==='end'?endDate:date" :visible="datePicker!==null" title="选择统计日期" @update:visible="v=>{if(!v)datePicker=null}" @confirm="setDate"/>
  <view v-if="zoneVisible" class="mask" @click="zoneVisible=false"><view class="drawer" @click.stop><strong>选择分区</strong><view class="options"><view :class="{active:!zone}" @click="selectZone('')">全部分区</view><view v-for="item in zones" :key="item" :class="{active:zone===item}" @click="selectZone(item)">{{item}}区</view></view></view></view>
  <view v-if="typeVisible" class="mask" @click="typeVisible=false"><view class="drawer" @click.stop><strong>选择货架类型</strong><view class="options"><view v-for="(item,index) in incomeTypes" :key="item" :class="{active:incomeType===index}" @click="selectType(index)">{{item}}</view></view></view></view>
</view></template>
<style scoped lang="scss">
.page{min-height:100vh;background:#fff}.tabs{border-bottom:1rpx solid var(--wms-border);white-space:nowrap}.tab-row{display:flex;width:max-content;min-width:100%;justify-content:space-around}.tabs text{display:flex;height:82rpx;align-items:center;margin:0 16rpx;border-bottom:5rpx solid transparent;color:var(--wms-text-secondary);font-size:21rpx}.tabs text.active{border-color:var(--wms-primary-700);color:var(--wms-primary-700);font-weight:750}.toolbar{display:flex;min-height:82rpx;align-items:center;gap:14rpx;padding:0 24rpx;font-size:21rpx}.toolbar>view{white-space:nowrap}.range>view{padding:10rpx 14rpx;border-radius:10rpx;background:var(--wms-background)}.income-filter input{width:170rpx;height:62rpx;padding:0 14rpx;border:1rpx solid var(--wms-border);border-radius:10rpx;font-size:20rpx}.income-filter .link,.cotton-filter .link{margin-left:auto;color:var(--wms-primary-700)}.cotton-filter{justify-content:space-between}.table .thead,.table .tr{display:grid;align-items:center;padding:0 22rpx}.table .thead{min-height:58rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx;font-weight:700}.table .tr{min-height:62rpx;margin-bottom:4rpx;background:#f1f3f3;font-size:20rpx}.two .thead,.two .tr{grid-template-columns:3fr 1fr}.three .thead,.three .tr{grid-template-columns:2fr 1fr 1.4fr}.income .thead,.income .tr{grid-template-columns:1.8fr 1.7fr .9fr 1fr;column-gap:8rpx}.income .tr{min-height:90rpx}.income .tr text{white-space:pre-line}.danger{color:var(--wms-danger)}.mask{position:fixed;z-index:60;inset:0;display:flex;align-items:flex-end;background:rgba(22,42,40,.45)}.drawer{box-sizing:border-box;width:100%;padding:28rpx 24rpx calc(30rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.drawer>strong{font-size:27rpx}.options{display:grid;grid-template-columns:repeat(3,1fr);gap:12rpx;margin-top:22rpx}.options view{display:flex;height:70rpx;align-items:center;justify-content:center;border-radius:10rpx;background:var(--wms-background);font-size:20rpx}.options view.active{background:var(--wms-surface-soft);color:var(--wms-primary-700);font-weight:700}
.toolbar{box-sizing:border-box;gap:12rpx;padding:12rpx 24rpx;background:var(--wms-background)}.filter-trigger{box-sizing:border-box;display:flex;height:64rpx;min-width:154rpx;align-items:center;justify-content:space-between;gap:10rpx;padding:0 14rpx;border:1rpx solid var(--wms-border);border-radius:12rpx;background:#fff;color:var(--wms-primary-700);font-size:19rpx}.filter-trigger text{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.filter-trigger i{width:0;height:0;flex:none;border-top:9rpx solid var(--wms-primary-700);border-right:7rpx solid transparent;border-left:7rpx solid transparent}.date-trigger{min-width:218rpx}.date-trigger .calendar-icon{flex:none;color:var(--wms-primary-700);font-size:20rpx}.range{justify-content:flex-start}.range .date-trigger{min-width:0;flex:1}.range-separator{flex:none;color:var(--wms-text-secondary);font-size:18rpx}.income-filter input{box-sizing:border-box;height:64rpx;background:#fff}.income-filter .date-trigger{min-width:205rpx}.income-filter .filter-trigger:last-child{min-width:150rpx}.cotton-filter{justify-content:flex-start}.cotton-filter .date-trigger{min-width:205rpx}.cotton-filter .filter-trigger:last-child{min-width:150rpx}.cotton-total{margin-left:auto;color:var(--wms-text-secondary);font-size:18rpx;white-space:nowrap}
</style>
